using System.Text;
using System.Text.Json;

namespace Chaos.IL2CPP.Tools.AutoTestGenerator;

public sealed class ProjectWriter
{
    public void WriteAll(
        string outputDir,
        string assemblyName,
        string typeFullName,
        string autoGeneratedSource,
        IReadOnlyList<ProbeResult> probeResults,
        CoverageReport report)
    {
        Directory.CreateDirectory(outputDir);

        // 1. AutoGenerated.cs
        var typeShortName = typeFullName.Split('.').LastOrDefault() ?? typeFullName;
        var csPath = Path.Combine(outputDir, $"{typeShortName}.AutoGenerated.cs");
        File.WriteAllText(csPath, autoGeneratedSource);
        Console.WriteLine($"[Output] {csPath}");

        // 2. .csproj
        var csprojPath = Path.Combine(outputDir, $"{typeShortName}.csproj");
        File.WriteAllText(csprojPath, GenerateCsproj(assemblyName));
        Console.WriteLine($"[Output] {csprojPath}");

        // 3. probe-results.json
        var probePath = Path.Combine(outputDir, "probe-results.json");
        var probeJson = JsonSerializer.Serialize(probeResults, new JsonSerializerOptions
        {
            WriteIndented = true,
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        });
        File.WriteAllText(probePath, probeJson);
        Console.WriteLine($"[Output] {probePath}");

        // 4. README.md
        var readmePath = Path.Combine(outputDir, "README.md");
        File.WriteAllText(readmePath, GenerateReadme(report));
        Console.WriteLine($"[Output] {readmePath}");
    }

    private string GenerateCsproj(string assemblyName)
    {
        var sdkDir = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "..",
                         "src", "reference", "Chaos.TestFramework.Sdk",
                         "Chaos.TestFramework.Sdk.csproj"));

        return
            "<Project Sdk=\"Microsoft.NET.Sdk\">\n" +
            "  <PropertyGroup>\n" +
            "    <OutputType>Exe</OutputType>\n" +
            "    <TargetFramework>net8.0</TargetFramework>\n" +
            "    <ImplicitUsings>enable</ImplicitUsings>\n" +
            "    <Nullable>enable</Nullable>\n" +
            "  </PropertyGroup>\n" +
            "  <ItemGroup>\n" +
           $"    <ProjectReference Include=\"{sdkDir}\" />\n" +
            "  </ItemGroup>\n" +
            "</Project>\n";
    }

    private string GenerateReadme(CoverageReport report)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"# AutoTestGenerator: {report.TypeName}");
        sb.AppendLine();
        sb.AppendLine($"- Assembly: `{report.AssemblyName}`");
        sb.AppendLine($"- Type: `{report.TypeName}`");
        sb.AppendLine();
        sb.AppendLine("## Coverage Summary");
        sb.AppendLine();
        sb.AppendLine($"| Metric | Value |");
        sb.AppendLine($"|--------|-------|");
        sb.AppendLine($"| Total Methods | {report.TotalMethods} |");
        sb.AppendLine($"| Auto-generated (Fact + Benchmark + HotUpdate) | {report.AutoGeneratedMethods} |");
        sb.AppendLine($"| Benchmark-only (pure void / non-deterministic) | {report.BenchmarkOnlyMethods} |");
        sb.AppendLine($"| Skipped (generic / unresolvable) | {report.SkippedMethods} |");
        sb.AppendLine($"| Total Subjects | {report.TotalSubjects} |");
        sb.AppendLine();
        sb.AppendLine("## Build");
        sb.AppendLine();
        sb.AppendLine("```bash");
        sb.AppendLine("# Build with verification (Assert enabled)");
        sb.AppendLine("dotnet build -p:DefineConstants=VERIFY");
        sb.AppendLine();
        sb.AppendLine("# Build for benchmark (Assert eliminated)");
        sb.AppendLine("dotnet build");
        sb.AppendLine("```");
        sb.AppendLine();
        sb.AppendLine("## Run");
        sb.AppendLine();
        sb.AppendLine("```bash");
        sb.AppendLine("# Run with verification");
        sb.AppendLine("dotnet run --project .");
        sb.AppendLine("```");

        if (report.SkippedMethodNames.Count > 0)
        {
            sb.AppendLine();
            sb.AppendLine("## Skipped Methods");
            sb.AppendLine();
            foreach (var name in report.SkippedMethodNames)
                sb.AppendLine($"- `{name}` — contains generic parameters, needs manual handling");
        }

        return sb.ToString();
    }
}
